import unittest
from search_filters import parse_filters

class SearchFilters(unittest.TestCase):
    def test_repeats_blanks_and_form_decoding(self):
        self.assertEqual(parse_filters('tag=red&tag=blue&note=&q=west+dock'), {
            'tag': ['red', 'blue'], 'note': [''], 'q': ['west dock']})
        self.assertEqual(parse_filters('flag&label=%E6%B8%AF%E5%8F%A3&literal=a%2Bb'), {
            'flag': [''], 'label': ['港口'], 'literal': ['a+b']})

    def test_only_ampersand_is_default_separator(self):
        self.assertEqual(parse_filters('route=north;south&x=a%26b'), {
            'route': ['north;south'], 'x': ['a&b']})

    def test_limit_counts_fields_before_merging_keys(self):
        self.assertEqual(parse_filters('tag=a&tag=b&tag=c&tag=d'), {'tag': ['a', 'b', 'c', 'd']})
        with self.assertRaises(ValueError):
            parse_filters('tag=a&tag=b&tag=c&tag=d&tag=e')
        with self.assertRaises(ValueError):
            parse_filters('a=&a=', max_fields=1)
        self.assertEqual(parse_filters('', max_fields=0), {})
        with self.assertRaises(ValueError):
            parse_filters('a=1', max_fields=0)

    def test_lenient_decoding_defaults(self):
        self.assertEqual(parse_filters('q=%ZZ&label=%FF&flag'),
                         {'q': ['%ZZ'], 'label': ['\ufffd'], 'flag': ['']})
        self.assertEqual(parse_filters('a=1&&'), {'a': ['1']})
        with self.assertRaises(ValueError):
            parse_filters('a=1&&', max_fields=2)

if __name__ == '__main__':
    unittest.main()

